def transform(grid):
    g = np.asarray(grid)
    h, w = g.shape
    out = np.zeros((2 * h, 2 * w), dtype=int)
    emit(out, "Allocate an empty canvas twice the input size; each input cell maps to a 2x2 block")
    motif = np.array([[1, 2], [2, 1]])
    for y in range(h):
        for x in range(w):
            if g[y, x] != 0:
                out[2 * y:2 * y + 2, 2 * x:2 * x + 2] = motif
                emit(out, f"Input cell ({y},{x}) is non-zero: stamp the 1/2 checker motif into its 2x2 block")
    emit(out, "All marked cells stamped; zero cells stay empty")
    return out
